#include <algorithm>
#include <iostream>
using namespace std;

void solve(istream& in, ostream& out) {
    int n;
    long long t;
    in >> n >> t;
    long long stock = 0, eaten = 0, previous = 1;
    for (int i = 0; i < n; ++i) {
        long long day, bales;
        in >> day >> bales;
        long long used = min(stock, day - previous);
        eaten += used;
        stock -= used;
        stock += bales;
        previous = day;
    }
    eaten += min(stock, t - previous + 1);
    out << eaten << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
