#include <iostream>
#include <string>
#include <vector>
using namespace std;

void solve(istream& in, ostream& out) {
    int tests;
    in >> tests;
    while (tests--) {
        int n, k;
        in >> n;
        vector<string> target(n);
        for (string& row : target) in >> row;
        in >> k;
        vector<string> stamp(k);
        for (string& row : stamp) in >> row;
        vector<vector<bool> > covered(n, vector<bool>(n, false));
        for (int rotation = 0; rotation < 4; ++rotation) {
            for (int top = 0; top + k <= n; ++top) {
                for (int left = 0; left + k <= n; ++left) {
                    bool safe = true;
                    for (int r = 0; r < k; ++r) {
                        for (int c = 0; c < k; ++c) {
                            if (stamp[r][c] == '*' && target[top + r][left + c] != '*')
                                safe = false;
                        }
                    }
                    if (safe) {
                        for (int r = 0; r < k; ++r) {
                            for (int c = 0; c < k; ++c) {
                                if (stamp[r][c] == '*') covered[top + r][left + c] = true;
                            }
                        }
                    }
                }
            }
            vector<string> next(k, string(k, '.'));
            for (int r = 0; r < k; ++r)
                for (int c = 0; c < k; ++c)
                    next[c][k - 1 - r] = stamp[r][c];
            stamp.swap(next);
        }
        bool possible = true;
        for (int r = 0; r < n; ++r)
            for (int c = 0; c < n; ++c)
                if (covered[r][c] != (target[r][c] == '*')) possible = false;
        out << (possible ? "YES" : "NO") << '\n';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
