#include <algorithm>
#include <iostream>
using namespace std;

void solve(istream& in, ostream& out) {
    int n;
    long long k, previous;
    in >> n >> k >> previous;
    long long cost = k + 1;
    for (int i = 1; i < n; ++i) {
        long long day;
        in >> day;
        cost += min(day - previous, k + 1);
        previous = day;
    }
    out << cost << '\n';
}

